import React from 'react';
import logo from '../logo.svg';

function Sidebar() {
  return (
    <aside className="menu has-background-white-ter p-5" style={{ minHeight: '100%', borderRight: '1px solid #eee' }}>
      <div className="has-text-centered mb-4">
        <img src={logo} alt="Developer" style={{ width: '80px', borderRadius: '50%', marginBottom: '1rem' }} />
        <h3 className="title is-5 mb-1">Developer</h3>
        <p className="subtitle is-7">Nida Hai</p>
      </div>
      <div>
        <p className="is-size-7 has-text-grey mb-2">Full Stack Developer passionate about React, Flask, and modern web technologies.</p>
        <p className="is-size-7 has-text-grey">Contact: nida.hai@email.com</p>
      </div>
    </aside>
  );
}

export default Sidebar;
